# owner: platform
import unittest
from hourglass.timesheet import timesheet_rows
from hourglass.models import Shift, Span
from hourglass.errors import ProjectError

def make_shift(name, day, start, end):
    return Shift(name, day, Span(start, end))

class TimesheetRowsTests(unittest.TestCase):
    def test_busiest_first(self):
        shifts = [
            make_shift("Odell", "mon", 540, 600),
            make_shift("Brisa", "mon", 540, 840),
            make_shift("Brisa", "tue", 540, 690)
        ]
        self.assertEqual(
            timesheet_rows(shifts),
            ["Brisa: shifts 2, hours 7.5", "Odell: shifts 1, hours 1.0"]
        )

    def test_one_decimal_place(self):
        rows = timesheet_rows([make_shift("Quill", "wed", 0, 20)])
        self.assertEqual(rows, ["Quill: shifts 1, hours 0.3"])

    def test_empty_list(self):
        with self.assertRaises(ProjectError):
            timesheet_rows([])

    def test_blank_worker(self):
        with self.assertRaises(ProjectError):
            timesheet_rows([make_shift("  ", "mon", 540, 600)])
